import subprocess, re, html
items={}
for u in ["https://assist.nat.gov.tw/wSite/lp?ctNode=232&mp=2&idPath=&pagesize=100",
          "https://assist.nat.gov.tw/wSite/lp?ctNode=232&mp=2&PageSize=100"]:
    t=subprocess.run(['curl','-sk','--max-time','30','-L',u],capture_output=True).stdout.decode('utf-8','replace')
    for m in re.finditer(r'href="(ct\?xItem=\d+&ctNode=232[^"]*)"[^>]*>(.*?)</a>', t):
        title=html.unescape(re.sub(r'<[^>]+>','',m.group(2))).strip()
        if title: items[m.group(1)]=title
    print(u.split('&')[-1], '->', len(items))
# fallback: page 1 and 2
for p in [1,2]:
    t=subprocess.run(['curl','-sk','--max-time','30','-L',f"https://assist.nat.gov.tw/wSite/lp?ctNode=232&mp=2&page={p}"],capture_output=True).stdout.decode('utf-8','replace')
    for m in re.finditer(r'href="(ct\?xItem=\d+&ctNode=232[^"]*)"[^>]*>(.*?)</a>', t):
        title=html.unescape(re.sub(r'<[^>]+>','',m.group(2))).strip()
        if title: items[m.group(1)]=title
    print('page',p,'->',len(items))
for k,v in items.items(): print(k,'|',v[:90])
EOF
